def f(inputs: List[Tuple[int, Tuple[int, int], List[Tuple[int, int]]]]) -> str:
    def find_intersect(vx: int, vy: int, points: List[Tuple[int, int]]) -> int:
        count = 0
        for x, y in points:
            if (vx * y - vy * x) % max(abs(vx), abs(vy)) == 0:
                count += 1
        return count

    result = []
    for n, (vx, vy), points in inputs:
        result.append(find_intersect(vx, vy, points))
    return''.join(map(str, result))
